                        "be": "Вёска Студзёнка, дзе ў лістападзе 1812 года праходзіла пераправа французскай арміі цераз Бярэзіну. Тут устаноўлены манумент \"Ахвярам вайны\" (2002), памятныя знакі на месцах \"верхняга\" і \"ніжняга\" мастоў, а таксама мемарыял з перапахаванымі астанкамі воінаў Вялікай арміі. У вёсцы таксама знаходзіцца дом-сядзіба І. Х. Каладзеева."
