                        "ru": "Один из ярких памятников архитектуры классицизма в Беларуси. Новое здание храма построено в 1806–1815 годах на месте прежнего деревянного костёла. Внешним видом напоминает античный храм с дорическим портиком на шесть колонн и треугольным фронтоном. Под хорами располагался семейный склеп Тышкевичей, где похоронен основатель храма граф Юзеф Тышкевич. В 1830 году перед костёлом появилась изящная брама-звонница с тремя бронзовыми колоколами. Внесён в Государственный список историко-культурных ценностей.",
                        "be": "Адзін з яскравых помнікаў архітэктуры класіцызму ў Беларусі. Новы будынак касцёла пабудаваны ў 1806–1815 гадах на месцы колішняга драўлянага касцёла. Вонкавым выглядам нагадвае антычны храм з дарычным порцікам на шэсць калон і трохкутным франтонам. Пад хорамі размяшчаўся сямейны склеп Тышкевічаў, дзе пахаваны заснавальнік храма граф Юзэф Тышкевіч. У 1830 годзе перад касцёлам з'явілася хупавая брама-званіца з трыма бронзавымі званамі. Унесены ў Дзяржаўны спіс гісторыка-культурных каштоўнасцей."
