                    "desc": {
                        "ru": "Республиканский ландшафтный заказник, уникальный для равнинного Полесья. Овраги и балки прорезают Мозырскую гряду, образованную около 250–300 тысяч лет назад. Глубина оврагов достигает 40–60 метров, крутизна склонов — до 30°. Здесь произрастает около 496 видов сосудистых растений, 14 из которых занесены в Красную книгу. Редкий реликт — клапагон европейский — в Беларуси встречается только здесь и в Беловежской пуще. На склонах обнажаются валуны ледниковой морены. Пейзаж, нехарактерный для Беларуси, за что заказник называют «белорусскими каньонами».",
                        "be": "Рэспубліканскі ландшафтны заказнік, унікальны для раўніннага Палесся. Яры і бэлькі праразаюць Мазырскую граду, утвораную каля 250-300 тысяч гадоў таму. Глыбіня яраў дасягае 40-60 метраў, крутасць схілаў - да 30 °. Тут расце каля 496 відаў судзінкавых раслін, 14 з якіх занесены ў Чырвоную кнігу. Рэдкі рэлікт - клапагон еўрапейскі - у Беларусі сустракаецца толькі тут і ў Белавежскай пушчы. На схілах агаляюцца валуны ледніковай марэны. Пейзаж, нехарактэрны для Беларусі, за што заказнік называюць \"беларускімі каньёнамі\"."
                    },
