                        "be": "Месца найбуйнейшай танкавай бітвы пачатковага перыяду Другой сусветнай вайны (Лепельскі контрудар, 6–10 ліпеня 1941 года). У памяць аб падзеі на Камсамольскай плошчы ўстаноўлены манумент \"Танк ІС-3\", а каля вёскі Новае Сяло - памятны знак да 75-годдзя бітвы. Унікальны ваенна-гістарычны аб'ект, звязаны з падзеяй, якая вызначыла ход вайны на пачатковым этапе."
